// Helper function to parse uptime output
function parseUptime(uptimeOutput) {
  try {
    // Example output: "13:14:15 up 38 days, 4:42, 1 user, load average: 0.00, 0.01, 0.05"
    const result = {
      raw: uptimeOutput.trim()
    };

    // Extract days up
    const daysMatch = uptimeOutput.match(/up\s+(\d+)\s+days?/);
    if (daysMatch) {
      result.days = parseInt(daysMatch[1], 10);
    } else {
      result.days = 0;
    }

    // Extract hours and minutes
    const timeMatch = uptimeOutput.match(/(?:(\d+):(\d+)(?:,|\s|$))/);
    if (timeMatch) {
      result.hours = parseInt(timeMatch[1], 10);
      result.minutes = parseInt(timeMatch[2], 10);
    } else {
      // Check for minutes only format
      const minsMatch = uptimeOutput.match(/up\s+(\d+)\s+min/);
      if (minsMatch) {
        result.hours = 0;
        result.minutes = parseInt(minsMatch[1], 10);
      } else {
        result.hours = 0;
        result.minutes = 0;
      }
    }

    // Extract load averages
    const loadMatch = uptimeOutput.match(/load average:\s+([\d.]+),\s+([\d.]+),\s+([\d.]+)/);
    if (loadMatch) {
      result.loadAvg = {
        "1min": parseFloat(loadMatch[1]),
        "5min": parseFloat(loadMatch[2]),
        "15min": parseFloat(loadMatch[3])
      };
    }

    // Calculate total uptime in hours for easy comparison
    result.totalHours = (result.days * 24) + result.hours + (result.minutes / 60);

    // Create a readable format
    result.readable = `${result.days} days, ${result.hours} hours, ${result.minutes} minutes`;

    return result;
  } catch (error) {
    console.error("Error parsing uptime:", error);
    return { raw: uptimeOutput.trim(), error: "Failed to parse uptime output" };
  }
}

// Improved helper function to parse CPU info with lscpu integration
function parseCpuInfo(cpuInfoOutput, lscpuOutput = '') {
  try {
    const result = {
      processors: 0,
      model: "Unknown",
      speed: "Unknown",
      cores: 0
    };

    // First try to get accurate CPU count from lscpu if available
    if (lscpuOutput) {
      // Get total CPU count
      const cpuCountMatch = lscpuOutput.match(/^CPU\(s\):\s+(\d+)/m);
      if (cpuCountMatch) {
        result.processors = parseInt(cpuCountMatch[1], 10);
        result.cores = result.processors; // Set cores equal to CPU count for virtual environments
      }

      // Try to get physical cores if available
      const coresPerSocketMatch = lscpuOutput.match(/^Core\(s\) per socket:\s+(\d+)/m);
      const socketsMatch = lscpuOutput.match(/^Socket\(s\):\s+(\d+)/m);

      if (coresPerSocketMatch && socketsMatch) {
        const coresPerSocket = parseInt(coresPerSocketMatch[1], 10);
        const sockets = parseInt(socketsMatch[1], 10);
        const physicalCores = coresPerSocket * sockets;

        // Only update if we got valid numbers
        if (!isNaN(physicalCores) && physicalCores > 0) {
          result.cores = physicalCores;
        }
      }
    }

    // Get CPU model and speed from cpuinfo
    const lines = cpuInfoOutput.split('\n');
    let processorCount = 0;

    // Find processor model from the first processor entry
    for (const line of lines) {
      if (line.includes('processor')) {
        processorCount++;
      }

      if (line.includes('model name') && result.model === "Unknown") {
        const modelMatch = line.match(/model name\s+:\s+(.*)/);
        if (modelMatch) {
          result.model = modelMatch[1].trim();
        }
      }

      if (line.includes('cpu MHz') && result.speed === "Unknown") {
        const speedMatch = line.match(/cpu MHz\s+:\s+(.*)/);
        if (speedMatch) {
          result.speed = `${parseFloat(speedMatch[1]).toFixed(2)} MHz`;
        }
      }
    }

    // If we didn't get CPU count from lscpu, use the processor count from cpuinfo
    if (result.processors === 0 && processorCount > 0) {
      result.processors = processorCount;

      // If cores is still 0, set it equal to processors
      if (result.cores === 0) {
        result.cores = processorCount;
      }
    }

    return result;
  } catch (error) {
    console.error("Error parsing CPU info:", error);
    return { 
      error: "Failed to parse CPU information",
      processors: 0,
      cores: 0,
      model: "Unknown",
      speed: "Unknown"
    };
  }
}

// Helper function to parse swap info from free -m output
function parseSwapInfo(freeOutput) {
  try {
    const lines = freeOutput.split('\n');
    // Find the Swap: line
    const swapLine = lines.find(line => line.includes('Swap:'));

    if (!swapLine) {
      return { available: false, message: "No swap information found" };
    }

    // Split by whitespace
    const swapParts = swapLine.trim().split(/\s+/);

    // In free -m output, after "Swap:", we expect: total, used, free
    if (swapParts.length >= 4) {
      // The first element is "Swap:", so we start from index 1
      const swapTotal = parseInt(swapParts[1], 10);
      const swapUsed = parseInt(swapParts[2], 10);
      const swapFree = parseInt(swapParts[3], 10);

      // Calculate swap percentage
      const swapPercent = swapTotal > 0 ? ((swapUsed / swapTotal) * 100).toFixed(1) : 0;

      return {
        available: true,
        total: `${(swapTotal / 1024).toFixed(2)}GB`,
        used: `${(swapUsed / 1024).toFixed(2)}GB`,
        free: `${(swapFree / 1024).toFixed(2)}GB`,
        usedPercent: swapPercent
      };
    }

    return { 
      available: false, 
      message: "Invalid swap line format",
      raw: swapLine.trim()
    };
  } catch (error) {
    console.error("Error parsing swap info:", error);
    return { 
      available: false, 
      error: "Failed to parse swap information" 
    };
  }
}

// Function to parse logged-in users
function parseWhoOutput(whoOutput) {
  try {
    const lines = whoOutput.trim().split('\n');
    const users = [];

    for (const line of lines) {
      if (line.trim()) {
        const parts = line.trim().split(/\s+/);
        if (parts.length >= 5) {
          users.push({
            username: parts[0],
            terminal: parts[1],
            loginDate: `${parts[2]} ${parts[3]}`,
            remoteHost: parts.length > 5 ? parts[4].replace(/\(|\)/g, '') : 'local'
          });
        }
      }
    }

    return {
      users: users,
      count: users.length
    };
  } catch (error) {
    console.error("Error parsing who output:", error);
    return { 
      error: "Failed to parse logged-in users information",
      raw: whoOutput.trim()
    };
  }
}

// Function to parse system boot time with complete date
function parseLastBootTime(bootOutput) {
  try {
    // Example output: "system boot  2023-10-08 08:49" or "system boot  Oct  8 08:49"
    const bootMatch = bootOutput.match(/system boot\s+(.+)/);
    if (bootMatch) {
      const bootTime = bootMatch[1].trim();

      // Check if the year is already included in the boot time
      const hasYear = /\d{4}/.test(bootTime);

      // If year is not included, add the current year or try to infer a reasonable year
      let fullBootTime = bootTime;
      if (!hasYear) {
        // Get current date for reference
        const now = new Date();
        const currentYear = now.getFullYear();

        // Add year to the boot time
        // Check if the boot time might be from a previous year
        const bootDate = new Date(`${bootTime} ${currentYear}`);
        if (bootDate > now) {
          // If the resulting date is in the future, assume it's from previous year
          fullBootTime = `${bootTime} ${currentYear - 1}`;
        } else {
          fullBootTime = `${bootTime} ${currentYear}`;
        }
      }

      // Try to format as a proper date
      try {
        const bootDate = new Date(fullBootTime);
        return {
          bootTime: fullBootTime, // Now with year
          bootDate: bootDate.toISOString(),
          readableTime: bootDate.toLocaleString(),
          rawBootTime: bootTime // Keep the original for reference
        };
      } catch (e) {
        // If date parsing fails, return the raw string
        return {
          bootTime: fullBootTime,
          rawBootTime: bootTime
        };
      }
    }

    return { 
      error: "Could not extract boot time",
      raw: bootOutput.trim()
    };
  } catch (error) {
    console.error("Error parsing boot time:", error);
    return { 
      error: "Failed to parse system boot time information",
      raw: bootOutput.trim() 
    };
  }
}

// Function to process a single server
async function processServer(server) {
  console.log(`Starting to process server: ${server.hostname}`);

  // Initialize result object
  const result = {
    hostname: server.hostname,
    username: server.username,
    timestamp: new Date().toISOString()
  };

  // Validate server data
  if (!server.hostname || !server.username || !server.password) {
    console.log(`Missing credentials for server ${server.hostname || 'unknown'}`);
    result.connected = false;
    result.error = {
      message: 'Missing required server credentials',
      details: 'Server must have hostname, username, and password'
    };
    return result;
  }

  // Initialize a new SSH client for this server
  const ssh = new NodeSSH();

  try {
    // Connect to the server
    console.log(`Connecting to ${server.hostname} as ${server.username}...`);
    await ssh.connect({
      host: server.hostname,
      username: server.username,
      password: server.password,
      port: 22,
      readyTimeout: 30000  // 30 second timeout
    });

    console.log(`Successfully connected to ${server.hostname}`);

    // Set connection status to success
    result.connected = true;
    result.metrics = {};

    // Step 1: Get OS info from SLES server
    console.log(`Getting OS info from ${server.hostname}...`);
    const osInfoCmd = 'cat /etc/os-release';
    const osInfo = await ssh.execCommand(osInfoCmd);

    if (osInfo.stdout) {
      // Parse OS release info using SLES-specific patterns
      const prettyNameMatch = osInfo.stdout.match(/PRETTY_NAME="([^"]+)"/);
      const versionIdMatch = osInfo.stdout.match(/VERSION_ID="([^"]+)"/);
      const idMatch = osInfo.stdout.match(/ID="([^"]+)"/);

      result.metrics.os = {
        name: prettyNameMatch ? prettyNameMatch[1] : 'unknown',
        version: versionIdMatch ? versionIdMatch[1] : 'unknown',
        id: idMatch ? idMatch[1] : 'SLES'
      };

      console.log(`OS info for ${server.hostname}: ${result.metrics.os.name} ${result.metrics.os.version}`);
    } else {
      console.log(`Failed to get OS info from ${server.hostname}. Error: ${osInfo.stderr}`);
      result.metrics.os = {
        name: 'SLES',
        version: 'unknown',
        error: osInfo.stderr || 'Could not retrieve OS information'
      };
    }

    // Step 2: Get memory and swap info
    console.log(`Getting memory info from ${server.hostname}...`);
    const memInfoCmd = 'free -m';
    const memInfo = await ssh.execCommand(memInfoCmd);

    if (memInfo.stdout) {
      const lines = memInfo.stdout.split('\n');

      // Find the Mem: line for memory info
      const memLine = lines.find(line => line.includes('Mem:'));

      if (memLine) {
        // Split by whitespace
        const memParts = memLine.trim().split(/\s+/);

        // In free -m output, after "Mem:", we expect: total, used, free, shared, buffers, cached
        if (memParts.length >= 4) {
          // The first element is "Mem:", so we start from index 1
          const memTotal = parseInt(memParts[1], 10);
          const memUsed = parseInt(memParts[2], 10);
          const memFree = parseInt(memParts[3], 10);

          // Calculate memory percentage
          const memPercent = memTotal > 0 ? ((memUsed / memTotal) * 100).toFixed(1) : 0;

          // Store the memory metrics
          result.metrics.memory = {
            total: `${(memTotal / 1024).toFixed(2)}GB`,
            used: `${(memUsed / 1024).toFixed(2)}GB`,
            free: `${(memFree / 1024).toFixed(2)}GB`,
            usedPercent: memPercent
          };

          console.log(`Memory info for ${server.hostname}: ${memUsed}MB used of ${memTotal}MB total (${memPercent}%)`);
        } else {
          console.log(`Unexpected format in memory info output for ${server.hostname}`);
          result.metrics.memory = {
            error: 'Could not parse memory information',
            raw: memLine
          };
        }
      } else {
        console.log(`No 'Mem:' line found in memory info for ${server.hostname}`);
        result.metrics.memory = {
          error: 'Could not find memory information',
          raw: memInfo.stdout.substring(0, 100) // Include part of the output for debugging
        };
      }

      // Process swap information from the same free -m output
      result.metrics.swap = parseSwapInfo(memInfo.stdout);
      console.log(`Swap info for ${server.hostname}: ${result.metrics.swap.available ? result.metrics.swap.usedPercent + '% used' : 'Not available'}`);
    } else {
      console.log(`Failed to get memory info from ${server.hostname}. Error: ${memInfo.stderr}`);
      result.metrics.memory = {
        error: memInfo.stderr || 'Could not retrieve memory information'
      };
      result.metrics.swap = {
        available: false,
        error: memInfo.stderr || 'Could not retrieve swap information'
      };
    }

    // Step 3: Get disk usage
    console.log(`Getting disk info from ${server.hostname}...`);
    const diskInfoCmd = 'df -h /';
    const diskInfo = await ssh.execCommand(diskInfoCmd);

    if (diskInfo.stdout) {
      const lines = diskInfo.stdout.split('\n');

      // df -h output has a header line and then data lines
      if (lines.length >= 2) {
        // Get the line with root filesystem data
        const diskLine = lines[1];
        const parts = diskLine.trim().split(/\s+/);

        // Standard df output: Filesystem, Size, Used, Avail, Use%, Mounted on
        if (parts.length >= 5) {
          result.metrics.disk = {
            filesystem: parts[0],
            total: parts[1],
            used: parts[2],
            available: parts[3],
            usedPercent: parts[4]
          };

          console.log(`Disk info for ${server.hostname}: ${parts[2]} used of ${parts[1]} total (${parts[4]})`);
        } else {
          console.log(`Unexpected format in disk info output for ${server.hostname}`);
          result.metrics.disk = {
            error: 'Could not parse disk information',
            raw: diskLine
          };
        }
      } else {
        console.log(`Insufficient output lines in disk info for ${server.hostname}`);
        result.metrics.disk = {
          error: 'Insufficient disk information output',
          raw: diskInfo.stdout
        };
      }
    } else {
      console.log(`Failed to get disk info from ${server.hostname}. Error: ${diskInfo.stderr}`);
      result.metrics.disk = {
        error: diskInfo.stderr || 'Could not retrieve disk information'
      };
    }

    // Step 4: Get uptime
    console.log(`Getting uptime from ${server.hostname}...`);
    const uptimeCmd = 'uptime';
    const uptimeInfo = await ssh.execCommand(uptimeCmd);

    if (uptimeInfo.stdout) {
      // Parse the uptime information
      result.metrics.uptime = parseUptime(uptimeInfo.stdout);
      console.log(`Uptime for ${server.hostname}: ${result.metrics.uptime.readable}`);
    } else {
      console.log(`Failed to get uptime from ${server.hostname}. Error: ${uptimeInfo.stderr}`);
      result.metrics.uptime = {
        error: uptimeInfo.stderr || 'Could not retrieve uptime information'
      };
    }

    // Step 5: Get CPU information (IMPROVED with lscpu)
    console.log(`Getting CPU info from ${server.hostname}...`);
    const lscpuCmd = 'lscpu';
    const lscpuInfo = await ssh.execCommand(lscpuCmd);
    let lscpuOutput = '';

    if (lscpuInfo.stdout) {
      lscpuOutput = lscpuInfo.stdout;
      console.log(`Successfully retrieved lscpu output from ${server.hostname}`);
    }

    // Also get cpuinfo for model name and other details
    const cpuInfoCmd = 'cat /proc/cpuinfo';
    const cpuInfo = await ssh.execCommand(cpuInfoCmd);

    if (cpuInfo.stdout) {
      // Parse the CPU information with both data sources
      result.metrics.cpu = parseCpuInfo(cpuInfo.stdout, lscpuOutput);
      console.log(`CPU info for ${server.hostname}: ${result.metrics.cpu.model}, ${result.metrics.cpu.processors} processors, ${result.metrics.cpu.cores} cores`);
    } else {
      console.log(`Failed to get CPU info from ${server.hostname}. Error: ${cpuInfo.stderr}`);
      result.metrics.cpu = {
        error: cpuInfo.stderr || 'Could not retrieve CPU information',
        processors: 0,
        cores: 0,
        model: "Unknown",
        speed: "Unknown"
      };
    }

    // Step 6: Get CPU usage
    console.log(`Getting CPU usage from ${server.hostname}...`);
    const cpuUsageCmd = 'top -bn1 | grep "Cpu(s)" | sed "s/.*, *\\([0-9.]*\\)%* id.*/\\1/" | awk \'{print 100 - $1}\'';
    const cpuUsageInfo = await ssh.execCommand(cpuUsageCmd);

    if (cpuUsageInfo.stdout) {
      const cpuUsage = parseFloat(cpuUsageInfo.stdout.trim());
      result.metrics.cpuUsage = {
        percent: isNaN(cpuUsage) ? 0 : cpuUsage.toFixed(1)
      };
      console.log(`CPU usage for ${server.hostname}: ${result.metrics.cpuUsage.percent}%`);
    } else {
      console.log(`Failed to get CPU usage from ${server.hostname}. Error: ${cpuUsageInfo.stderr}`);
      result.metrics.cpuUsage = {
        error: cpuUsageInfo.stderr || 'Could not retrieve CPU usage information'
      };
    }

    // Step 7: Get kernel version
    console.log(`Getting kernel version from ${server.hostname}...`);
    const kernelCmd = 'uname -r';
    const kernelInfo = await ssh.execCommand(kernelCmd);

    if (kernelInfo.stdout) {
      result.metrics.kernel = {
        version: kernelInfo.stdout.trim()
      };
      console.log(`Kernel version for ${server.hostname}: ${result.metrics.kernel.version}`);
    } else {
      console.log(`Failed to get kernel version from ${server.hostname}. Error: ${kernelInfo.stderr}`);
      result.metrics.kernel = {
        error: kernelInfo.stderr || 'Could not retrieve kernel version'
      };
    }

    // Step 8: Get network interface information (FIXED)
    console.log(`Getting network info from ${server.hostname}...`);

    // Use a direct command to get the IP address for each interface - more reliable
    const directIpCmd = 'for iface in $(ip -o link show | grep -v "lo:" | cut -d: -f2 | tr -d " "); do echo "IFACE:$iface"; ip addr show dev $iface | grep "inet " | awk \'{print $2}\'; done';
    const directIpInfo = await ssh.execCommand(directIpCmd);

    // Also get general interface info
    const networkCmd = 'ip addr show; ip link show';
    const networkInfo = await ssh.execCommand(networkCmd);

    // Initialize interfaces array
    const interfaces = [];

    // Process direct IP command results first
    if (directIpInfo.stdout) {
      console.log(`Direct IP command output: ${directIpInfo.stdout}`);
      const lines = directIpInfo.stdout.split('\n');
      let currentIface = null;

      for (const line of lines) {
        if (line.startsWith('IFACE:')) {
          currentIface = {
            name: line.substring(6).trim(),
            ipv4: [],
            status: 'unknown',
            mac: 'N/A'
          };
          interfaces.push(currentIface);
        } else if (currentIface && line.trim()) {
          // This should be an IP address
          const ipMatch = line.match(/([0-9.]+)\/(\d+)/);
          if (ipMatch) {
            currentIface.ipv4.push({
              address: ipMatch[1],
              netmask: ipMatch[2]
            });
          }
        }
      }
    }

    // Now get more interface details from ip addr/link output
    if (networkInfo.stdout) {
      const lines = networkInfo.stdout.split('\n');

      // Find status and MAC for each interface
      for (const line of lines) {
        // Interface name
        const interfaceMatch = line.match(/^\d+:\s+(\w+):/);
        if (interfaceMatch) {
          const ifaceName = interfaceMatch[1].trim();

          // Skip loopback
          if (ifaceName === 'lo') continue;

          // Find or create this interface
          let iface = interfaces.find(i => i.name === ifaceName);
          if (!iface) {
            iface = {
              name: ifaceName,
              ipv4: [],
              status: 'down',
              mac: 'N/A'
            };
            interfaces.push(iface);
          }

          // Check status
          if (line.includes('UP') || line.includes('LOWER_UP')) {
            iface.status = 'up';
          }
        }

        // MAC address
        const macMatch = line.match(/link\/ether\s+([0-9a-f:]+)/);
        if (macMatch) {
          // Find the interface this belongs to
          const prevLine = lines[lines.indexOf(line) - 1] || '';
          const interfaceMatch = prevLine.match(/^\d+:\s+(\w+):/);
          if (interfaceMatch) {
            const ifaceName = interfaceMatch[1].trim();
            const iface = interfaces.find(i => i.name === ifaceName);
            if (iface) {
              iface.mac = macMatch[1];
            }
          }
        }

        // Additional IP check
        const ipMatch = line.match(/inet\s+([0-9.]+)\/(\d+)/);
        if (ipMatch) {
          const prevLine = lines[lines.indexOf(line) - 1] || '';
          const prevPrevLine = lines[lines.indexOf(line) - 2] || '';

          // Find which interface this belongs to
          const interfaceMatchCurrent = prevLine.match(/^\d+:\s+(\w+):/);
          const interfaceMatchPrev = prevPrevLine.match(/^\d+:\s+(\w+):/);

          if (interfaceMatchCurrent) {
            const ifaceName = interfaceMatchCurrent[1].trim();
            let iface = interfaces.find(i => i.name === ifaceName);
            if (!iface) {
              iface = {
                name: ifaceName,
                ipv4: [],
                status: 'unknown',
                mac: 'N/A'
              };
              interfaces.push(iface);
            }

            // Check if this IP is already in the list
            if (!iface.ipv4.some(ip => ip.address === ipMatch[1])) {
              iface.ipv4.push({
                address: ipMatch[1],
                netmask: ipMatch[2]
              });
            }
          } else if (interfaceMatchPrev) {
            const ifaceName = interfaceMatchPrev[1].trim();
            let iface = interfaces.find(i => i.name === ifaceName);
            if (!iface) {
              iface = {
                name: ifaceName,
                ipv4: [],
                status: 'unknown',
                mac: 'N/A'
              };
              interfaces.push(iface);
            }

            // Check if this IP is already in the list
            if (!iface.ipv4.some(ip => ip.address === ipMatch[1])) {
              iface.ipv4.push({
                address: ipMatch[1],
                netmask: ipMatch[2]
              });
            }
          }
        }
      }
    }

    // Last resort - get IPs with a different command
    if (interfaces.every(iface => iface.ipv4.length === 0)) {
      const ifconfigCmd = 'ifconfig -a';
      const ifconfigInfo = await ssh.execCommand(ifconfigCmd);

      if (ifconfigInfo.stdout) {
        console.log(`Falling back to ifconfig output for ${server.hostname}`);
        const sections = ifconfigInfo.stdout.split(/\n\n+/);

        for (const section of sections) {
          const lines = section.split('\n');
          const ifaceMatch = lines[0].match(/^(\w+):/);

          if (ifaceMatch && ifaceMatch[1] !== 'lo') {
            const ifaceName = ifaceMatch[1];
