            name: proc.name,
            mode: proc.pm2_env?.exec_mode || 'unknown',
            status: proc.pm2_env?.status || 'unknown',
            memory: proc.monit?.memory ? Math.round(proc.monit.memory / (1024 * 1024)) + 'mb' : '0mb',
            cpu: proc.monit?.cpu ? parseFloat(proc.monit.cpu.toFixed(1)) + '%' : '0%'
          }));

          activeApps = processes.filter(p => p.pm2_env?.status === 'online').length;
